const upsertDashboardPreferences = `-- name: UpsertDashboardPreferences :one
INSERT INTO dashboard_preferences (account_id, widgets, default_property_id, updated_at) VALUES ($1, $2, $3, $4)
ON CONFLICT (account_id) DO UPDATE SET widgets = EXCLUDED.widgets, default_property_id = EXCLUDED.default_property_id, updated_at = EXCLUDED.updated_at
RETURNING account_id, widgets, default_property_id, updated_at
`

type UpsertDashboardPreferencesParams struct {
	AccountID         ids.ID
	Widgets           []string
	DefaultPropertyID *ids.ID
	UpdatedAt         time.Time
}

func (q *Queries) UpsertDashboardPreferences(ctx context.Context, db DBTX, arg UpsertDashboardPreferencesParams) (DashboardPreference, error) {
	row := db.QueryRow(ctx, upsertDashboardPreferences,
		arg.AccountID,
		arg.Widgets,
		arg.DefaultPropertyID,
		arg.UpdatedAt,
	)
	var i DashboardPreference
	err := row.Scan(
		&i.AccountID,
		&i.Widgets,
		&i.DefaultPropertyID,
		&i.UpdatedAt,
	)
	return i, err
}
